package egovframework.let.solution.service.impl;



import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import javax.transaction.Transactional;
import javax.validation.ValidationException;

import org.modelmapper.ModelMapper;
import org.springframework.stereotype.Service;

import egovframework.com.cmm.EgovMessageSource;
import egovframework.com.cmm.dto.PagingWrapper;
import egovframework.com.cmm.exception.CustomException;
import egovframework.com.cmm.param.BasePagingParam;
import egovframework.com.cmm.util.AppUtil;
import egovframework.let.file.service.FileService;
import egovframework.let.solution.dto.SolutionContentDto;
import egovframework.let.solution.dto.SolutionTypeDto;
import egovframework.let.solution.entity.SolutionContentEntity;
import egovframework.let.solution.entity.SolutionTypeEntity;
import egovframework.let.solution.param.AddSolutionContentParam;
import egovframework.let.solution.param.AddSolutionTypeParam;
import egovframework.let.solution.param.FindAllSolutionContentParam;
import egovframework.let.solution.param.UpdateSolutionContentParam;
import egovframework.let.solution.param.UpdateSolutionTypeParam;
import egovframework.let.solution.service.EgovSolutionService;
import lombok.RequiredArgsConstructor;

@Service
@RequiredArgsConstructor
public class EgovSolutionServiceImpl implements EgovSolutionService {
	private final SolutionDAO solutionDAO;
	private final ModelMapper modelMapper;
	private final FileService fileService;
	private final EgovMessageSource messageService;
	
	private String getTypeIconUrl(long typeId) {
		List<String> allUrls = fileService.getAllFilesByEntity(AppUtil.ENTITY_SOLUTION_TYPE, String.valueOf(typeId));
		if (allUrls != null && !allUrls.isEmpty()) {
			return allUrls.get(0);
		}
		
		String typeStr = String.valueOf(typeId);
		return switch (typeStr) {
			case "1" -> "data:image/png;base64,";
			case "2" -> "data:image/png;base64,";
			case "3" -> "data:image/png;base64,";
			case "4" -> "data:image/png;base64,";
			default -> "";
		};
	}
	
	private String getContentIconUrl(long contentId) {
		List<String> allUrls = fileService.getAllFilesByEntity(AppUtil.ENTITY_SOLUTION_CONTENT, String.valueOf(contentId));
		if (allUrls != null && !allUrls.isEmpty()) {
			return allUrls.get(0);
		}

		String typeStr = String.valueOf(contentId);
		return switch (typeStr) {
			case "1" -> "data:image/png;base64,";
			case "2" -> "data:image/png;base64,";
			case "3" -> "data:image/png;base64,";
			case "4" -> "data:image/png;base64,";
			case "5" -> "data:image/png;base64,";
			case "6" -> "data:image/png;base64,";
			case "7" -> "data:image/png;base64,";
			case "8" -> "data:image/png;base64,";
			case "9" -> "data:image/png;base64,";
			case "10" -> "data:image/png;base64,";
			case "11" -> "data:image/png;base64,";
			case "12" -> "data:image/png;base64,";
			case "13" -> "data:image/png;base64,";
			default -> "";
		};
	}
	
	@Override
	public PagingWrapper<SolutionTypeDto> findAllSolutionType(BasePagingParam param) {
		// create sql params;
		Map<String, Object> sqlParam = new HashMap<>();
		sqlParam.put("page", param.getPage());
		sqlParam.put("limit", param.getLimit());
		
		long totalItems = solutionDAO.countAllSolutionType(sqlParam).orElse(0L);
		
		if (totalItems == 0) { //if length is 0 => return immediately without querying more data
            return PagingWrapper.<SolutionTypeDto>builder()
                    .data(Collections.emptyList())
                    .meta(PagingWrapper.MetaData.builder()
                            .totalItems(0)
                            .totalPages(0)
                            .build())
                    .build();
        }
		
		 //calculate total pages, then round up
        long totalPages = (long) Math.ceil((double) totalItems / param.getLimit());
        
        List<SolutionTypeDto> types = solutionDAO.findAllSolutionType(sqlParam);
        types.forEach(type -> {
    		type.setIconUrl(getTypeIconUrl(type.getId()));
        });
		
        return PagingWrapper.<SolutionTypeDto>builder()
                .data(types)
                .meta(PagingWrapper.MetaData.builder()
                        .totalItems(totalItems)
                        .totalPages(totalPages)
                        .build())
                .build();
	}

	@Override
	public SolutionTypeDto findSolutionTypeById(long id) {
		SolutionTypeDto type = solutionDAO.findSolutionTypeById(id)
				.orElseThrow(() -> new ValidationException(messageService.get("solution-type.not-found")));
		
		type.setIconUrl(getTypeIconUrl(type.getId()));
		return type;
	}
	

	@Transactional
	@Override
	public SolutionTypeDto addNewSolutionType(AddSolutionTypeParam param) {
		SolutionTypeEntity newType = modelMapper.map(param, SolutionTypeEntity.class);
		if (solutionDAO.addSolutionType(newType) <= 0) {
			throw new CustomException(messageService.get("solution-type.insert.failed"));
		}
		
		// add file if necessary
		if (param.getIconFile() != null && !param.getIconFile().isEmpty()) {
			fileService.addFilesToEntity(AppUtil.ENTITY_SOLUTION_TYPE, String.valueOf(newType.getId()),
					List.of(param.getIconFile()));
		}
		

		return findSolutionTypeById(newType.getId());
	}


	@Transactional
	@Override
	public SolutionTypeDto updateSolutionType(UpdateSolutionTypeParam param) {
		// validate exists
		if (solutionDAO.findSolutionTypeById(param.getId()).isEmpty()) {
			throw new ValidationException(messageService.get("solution-type.not-found"));
		}
		
		// update
		SolutionTypeEntity updatedType = modelMapper.map(param, SolutionTypeEntity.class);
		if (solutionDAO.updateSolutionType(updatedType) <= 0) {
			throw new CustomException(messageService.get("solution-type.update.failed"));
		}
		
		// update file if necessary
		if (param.getIconFile() != null && !param.getIconFile().isEmpty()) {
			// delete old file
			fileService.deleteEntityFiles(AppUtil.ENTITY_SOLUTION_TYPE, String.valueOf(param.getId()));
			
			// add new file
			fileService.addFilesToEntity(AppUtil.ENTITY_SOLUTION_TYPE, String.valueOf(param.getId()),
					List.of(param.getIconFile()));
		}
		
		return findSolutionTypeById(param.getId());
	}


	@Transactional
	@Override
	public void deleteSolutionTypeById(long id) {
		// validate exists
		if (solutionDAO.findSolutionTypeById(id).isEmpty()) {
			throw new ValidationException(messageService.get("solution-type.not-found"));
		}
		
		// find all child IDS to delete first
		List<Long> contentIds = solutionDAO.findAllSolutionContentIdByType(id);
		contentIds.forEach(contentId -> deleteSolutionContentById(contentId));
		
		// delete parent
		if (solutionDAO.deleteSolutionType(id) <= 0) {
			throw new CustomException(messageService.get("solution-type.delete.failed"));
		}
		
		// delete parent files
		fileService.deleteEntityFiles(AppUtil.ENTITY_SOLUTION_TYPE, String.valueOf(id));
	}

	@Override
	public PagingWrapper<SolutionContentDto> findAllSolutionContent(FindAllSolutionContentParam param) {
		// validate solution type
		if (param.getTypeId() != null && 
				solutionDAO.findSolutionTypeById(param.getTypeId()).isEmpty()) {
			throw new ValidationException(messageService.get("solution-type.not-found"));
		}
		
		// create sql params;
		Map<String, Object> sqlParam = new HashMap<>();
		sqlParam.put("page", param.getPage());
		sqlParam.put("limit", param.getLimit());
		sqlParam.put("typeId", param.getTypeId());
		
		long totalItems = solutionDAO.countAllSolutionContent(sqlParam).orElse(0L);
		
		if (totalItems == 0) { //if length is 0 => return immediately without querying more data
            return PagingWrapper.<SolutionContentDto>builder()
                    .data(Collections.emptyList())
                    .meta(PagingWrapper.MetaData.builder()
                            .totalItems(0)
                            .totalPages(0)
                            .build())
                    .build();
        }
		
		 //calculate total pages, then round up
        long totalPages = (long) Math.ceil((double) totalItems / param.getLimit());
        
        List<SolutionContentDto> contents = solutionDAO.findAllSolutionContent(sqlParam);
        contents.forEach(content -> {
        	content.setIconUrl(getContentIconUrl(content.getId()));
        });
		
        return PagingWrapper.<SolutionContentDto>builder()
                .data(contents)
                .meta(PagingWrapper.MetaData.builder()
                        .totalItems(totalItems)
                        .totalPages(totalPages)
                        .build())
                .build();
	}

	@Override
	public SolutionContentDto findSolutionContentById(long id) {
		SolutionContentDto content = solutionDAO.findSolutionContentById(id)
				.orElseThrow(() -> new ValidationException(messageService.get("solution-type.not-found")));
		
		content.setIconUrl(getContentIconUrl(content.getId()));
		return content;
	}

	@Transactional
	@Override
	public SolutionContentDto addNewSolutionContent(AddSolutionContentParam param) {
		// validate solution type
		if (solutionDAO.findSolutionTypeById(param.getTypeId()).isEmpty()) {
			throw new ValidationException(messageService.get("solution-type.not-found"));
		}
		
		SolutionContentEntity newContent = modelMapper.map(param, SolutionContentEntity.class);
		if (solutionDAO.addSolutionContent(newContent) <= 0) {
			throw new CustomException(messageService.get("solution-content.insert.failed"));
		}
		
		// add file if necessary
		if (param.getIconFile() != null && !param.getIconFile().isEmpty()) {
			fileService.addFilesToEntity(AppUtil.ENTITY_SOLUTION_CONTENT, String.valueOf(newContent.getId()),
					List.of(param.getIconFile()));
		}
		

		return findSolutionContentById(newContent.getId());
	}

	@Transactional
	@Override
	public SolutionContentDto updateSolutionContent(UpdateSolutionContentParam param) {
		//validate exists
		if (solutionDAO.findSolutionContentById(param.getId()).isEmpty()) {
			throw new ValidationException(messageService.get("solution-content.not-found"));
		}
		
		SolutionContentEntity updatedContent = modelMapper.map(param, SolutionContentEntity.class);
		if (solutionDAO.updateSolutionContent(updatedContent) <= 0) {
			throw new CustomException(messageService.get("solution-content.update.failed"));
		}
		
		// update file if necessary
		if (param.getIconFile() != null && !param.getIconFile().isEmpty()) {
			// delete old file
			fileService.deleteEntityFiles(AppUtil.ENTITY_SOLUTION_CONTENT, String.valueOf(updatedContent.getId()));
			
			// add new file
			fileService.addFilesToEntity(AppUtil.ENTITY_SOLUTION_CONTENT, String.valueOf(updatedContent.getId()),
					List.of(param.getIconFile()));
		}

		return findSolutionContentById(updatedContent.getId());
	}
	
	@Transactional
	@Override
	public SolutionContentDto updateSolutionContentDescription(long id, Object description) {
		//validate exists
		if (solutionDAO.findSolutionContentById(id).isEmpty()) {
			throw new ValidationException(messageService.get("solution-content.not-found"));
		}
		
		SolutionContentEntity updatedContent = SolutionContentEntity.builder()
				.id(id)
				.description(description)
				.build();
		if (solutionDAO.updateSolutionContent(updatedContent) <= 0) {
			throw new CustomException(messageService.get("solution-content.update.failed"));
		}
		
		return findSolutionContentById(updatedContent.getId());
	}

	@Transactional
	@Override
	public void deleteSolutionContentById(long id) {
		// validate exists
		if (solutionDAO.findSolutionContentById(id).isEmpty()) {
			throw new ValidationException(messageService.get("solution-content.not-found"));
		}
		
		// delete
		if (solutionDAO.deleteSolutionContent(id) <= 0) {
			throw new CustomException(messageService.get("solution-type.delete.failed"));
		}
		
		// delete files
		fileService.deleteEntityFiles(AppUtil.ENTITY_SOLUTION_CONTENT, String.valueOf(id));
	}
}
